(()=>{const products=[];for(const [vehicle,prefix,route] of [['Porsche 911','porsche','porsche-911.html#configurator'],['Golf R Mk7','golf','golf-r.html#finishes'],['Audi S3 8V','s3','audi-s3.html#configurator']]){const isS3=prefix==='s3';
  const items=[
    ['wheels','Custom wheel set','Wheels','Choose your spoke design and discuss sizing for your vehicle.',isS3?'s3-rear-custom.png':prefix==='golf'?'golf-rear-split.png':'porsche-sport.png',''],
    isS3?null:['lip','Carbon front lip','Aero','A sharper front-end finish, quoted with installation.',isS3?'s3-front-custom.png':prefix+'-front-lip.png',''],
    isS3?null:['diffuser','Carbon rear diffuser','Aero','Define the rear profile with a carbon-finish aero option.',isS3?'s3-rear-custom.png':prefix+'-rear-aero.png',''],
    isS3?null:['steering','Custom steering wheel','Steering wheels','Leather, carbon or Alcantara. Choose your finish in the build studio.',prefix+'-steering.png','steering'],
    isS3?null:['tips','Oval exhaust tips','Exhaust tips','A finishing detail for your rear build. Fitment checked before ordering.',isS3?'s3-rear-custom.png':prefix+'-rear-aero.png','']
  ].filter(Boolean);
  for(const [slug,name,category,desc,img,style] of items)products.push({id:prefix+'-'+slug,name,vehicle,category,desc,img,style,route});
  if(isS3)products.push({id:'s3-kit',name:'HOC aero + wheels pack',vehicle,category:'Aero',desc:'Front splitter, rear diffuser and black multi-spoke wheels, quoted as one pack with installation.',img:'s3-front-custom.png',style:'',route});}
const tunes=(window.HOC_DATA.vehicles||[]).filter(v=>v.tunes&&v.tunes.length).forEach(v=>v.tunes.forEach(t=>products.push({id:'tune-'+v.id+'-'+t.stage.replace(/\s+/g,'').toLowerCase(),name:t.stage+' software · '+v.brand+' '+v.model+' '+v.gen,vehicle:v.brand+' '+v.model+(v.id==='vw-golf-r-mk7'?' Mk7':' '+(v.gen||'')),category:'Software',desc:(t.stock?t.stock+' stock → '+t.tuned+' after software. ':'Software figures published on the manufacturer page for this engine. ')+(t.note||'')+' Fuel: '+(t.fuel||'see source')+'. ECU code required to confirm availability.',img:'',style:'',route:'build.html#configurator'})));
const target=document.querySelector('#products'),vehicle=document.querySelector('#shop-vehicle'),category=document.querySelector('#shop-category'),search=document.querySelector('#shop-search');
function render(){const q=search.value.trim().toLowerCase();const list=products.filter(p=>(vehicle.value==='all'||p.vehicle===vehicle.value)&&(category.value==='all'||p.category===category.value)&&(!q||(p.name+' '+p.desc+' '+p.vehicle).toLowerCase().includes(q)));target.replaceChildren();for(const p of list){const card=document.createElement('article');card.className='product';card.innerHTML=`<div class="product-visual ${p.style||('detail-'+p.id.split('-').pop())}" style="background-image:url('${p.img}')" role="img" aria-label="${p.name} design option"></div><span class="tag">${p.vehicle}</span><h3>${p.name}</h3><p>${p.desc}</p><p class="price">Request a quote</p><button class="outline-cta">${window.hocQuote.has(p.id)?'Added to quote ✓':'Add to quote +'}</button><a class="text-link" href="${p.route}">Preview your build ↗</a>`;card.querySelector('button').onclick=()=>{window.hocQuote.add({id:p.id,name:p.name,vehicle:p.vehicle});card.querySelector('button').textContent='Added to quote ✓'};target.append(card)}document.querySelector('#result-count').textContent=list.length+' design options';document.querySelector('#no-results').hidden=!!list.length}
[vehicle,category].forEach(x=>x.onchange=render);search.oninput=render;document.querySelector('#view-quote').onclick=()=>window.hocQuote.open();window.addEventListener('hoc-cart-change',render);render();})();
